const text = $input.first().json.section;
// Match sentences ending with ., ! or ?
const sentences = text.match(/[^.!?]+[.!?]+/g) || [text];

return sentences.map(s => ({
  json: { sentence: s.trim() }
}));

// Code / Function node: combine current items
const audio_ids = items.map(i => i.json.audio_id).filter(Boolean);
if (!audio_ids.length) throw new Error('No audio_ids on input items');

return [{
  json: {
    audio_ids
  }
}];
